-- Dumping structure for procedure spire.generate_id
DROP PROCEDURE IF EXISTS `generate_id`;
DELIMITER //
CREATE PROCEDURE `generate_id`(
    IN `prefix` CHAR(8),
    IN `table_name` VARCHAR(255),
    OUT `new_id` CHAR(8)
)
BEGIN
    DECLARE current_max_id CHAR(8) DEFAULT NULL;
    DECLARE new_number INT DEFAULT 1;
    DECLARE id_exists INT;

    -- Construct the full prefix to match
    SET @full_prefix = CONCAT(prefix, '%');
    
    -- Find the current max ID that matches the prefix (without dynamic SQL)
    SET @sql = CONCAT('SELECT MAX(id) INTO @current_max_id FROM ', table_name, ' WHERE id LIKE "', @full_prefix, '"');
    PREPARE stmt FROM @sql;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;

    -- Extract numeric part and increment it if we found an ID
    IF @current_max_id IS NOT NULL THEN
        SET new_number = CAST(SUBSTRING(@current_max_id, LENGTH(prefix) + 1) AS UNSIGNED) + 1;
    END IF;

    -- Generate new ID
    SET new_id = CONCAT(prefix, LPAD(new_number, 6, '0'));

    -- Check if the generated ID already exists
    SET @sql = CONCAT('SELECT COUNT(*) INTO @id_exists FROM ', table_name, ' WHERE id = "', new_id, '"');
    PREPARE stmt FROM @sql;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;

    -- If ID exists, keep generating new IDs until unique
    SELECT @id_exists INTO id_exists;
    WHILE id_exists > 0 DO
        SET new_number = new_number + 1;
        SET new_id = CONCAT(prefix, LPAD(new_number, 6, '0'));

        -- Check again
        SET @sql = CONCAT('SELECT COUNT(*) INTO @id_exists FROM ', table_name, ' WHERE id = "', new_id, '"');
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
        
        SELECT @id_exists INTO id_exists;
    END WHILE;

END//
DELIMITER ;

