DROP PROCEDURE IF EXISTS `RepairReimbursementVouchers_Final`;
DELIMITER //
CREATE PROCEDURE `RepairReimbursementVouchers_Final`()
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE v_id INT;
    DECLARE v_project_id CHAR(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE v_old_custom_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE v_created_at DATETIME;
    
    DECLARE v_old_prefix VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE v_new_prefix VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE v_short_year VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE v_seq_key VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE v_new_custom_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE current_seq INT;

    -- 1. Pull ONLY records that are NOT 2024-25, sorted perfectly by creation date
    DECLARE cur CURSOR FOR 
        SELECT id, project_id, custom_id, created_at
        FROM rv
        WHERE custom_id NOT LIKE '%2024-25%'
        ORDER BY created_at ASC, id ASC;
        
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    -- 2. Temporary table to track sequence counts per prefix and year
    DROP TEMPORARY TABLE IF EXISTS seq_tracker_rv;
    CREATE TEMPORARY TABLE seq_tracker_rv (
        seq_key VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci PRIMARY KEY,
        seq_val INT
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

    -- 3. Temporary table to hold the finalized mappings before the live update
    DROP TEMPORARY TABLE IF EXISTS rv_updates;
    CREATE TEMPORARY TABLE rv_updates (
        id INT PRIMARY KEY,
        project_id CHAR(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
        old_custom_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
        new_custom_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO v_id, v_project_id, v_old_custom_id, v_created_at;
        IF done THEN LEAVE read_loop; END IF;

        SET v_old_prefix = TRIM(SUBSTRING_INDEX(v_old_custom_id, '/', 1));

        -- 4. The Translation Engine (Forcing RSD to RSDS)
        SET v_new_prefix = CASE 
            WHEN v_old_prefix IN ('SCL', 'PSCL', 'RSD') THEN 'RSDS'
            WHEN v_old_prefix IN ('SA', 'RSA') THEN 'RSA'
            WHEN v_old_prefix IN ('AG', 'RAG') THEN 'RAG'
            ELSE v_old_prefix 
        END;

        -- 5. Math for Short Year (Bypassing the NaN corruption)
        IF v_created_at IS NULL THEN
            SET v_short_year = '25-26'; 
        ELSEIF MONTH(v_created_at) >= 4 THEN
            SET v_short_year = CONCAT(DATE_FORMAT(v_created_at, '%y'), '-', DATE_FORMAT(DATE_ADD(v_created_at, INTERVAL 1 YEAR), '%y'));
        ELSE
            SET v_short_year = CONCAT(DATE_FORMAT(DATE_SUB(v_created_at, INTERVAL 1 YEAR), '%y'), '-', DATE_FORMAT(v_created_at, '%y'));
        END IF;

        SET v_seq_key = CONCAT(v_new_prefix, '_', v_short_year);

        IF NOT EXISTS (SELECT 1 FROM seq_tracker_rv WHERE seq_key = v_seq_key) THEN
        END IF;

        SELECT seq_val INTO current_seq FROM seq_tracker_rv WHERE seq_key = v_seq_key;
        SET current_seq = current_seq + 1;
        UPDATE seq_tracker_rv SET seq_val = current_seq WHERE seq_key = v_seq_key;

        SET v_new_custom_id = CONCAT(v_new_prefix, '/', v_short_year, '/', LPAD(current_seq, 5, '0'));

        VALUES (v_id, v_project_id, v_old_custom_id, v_new_custom_id);

    END LOOP;
    CLOSE cur;

    -- =========================================================================
    -- THE SYNC: Safely update both tables using the project_id bridge
    -- =========================================================================
    
    -- Update Transactions First
    UPDATE rv_transactions t
    JOIN rv_updates u ON t.project_id = u.project_id
    SET t.rv_custom_id = u.new_custom_id;

    -- Update Vouchers Second
    UPDATE rv r
    JOIN rv_updates u ON r.id = u.id
    SET r.custom_id = u.new_custom_id;

    -- Cleanup memory
    DROP TEMPORARY TABLE IF EXISTS seq_tracker_rv;
    DROP TEMPORARY TABLE IF EXISTS rv_updates;

END//
DELIMITER ;

