  `payment_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `remarks` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `entry_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `entry_by_id` char(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_vt_vendor_id` (`vendor_id`),
  KEY `fk_vt_bank_id` (`bank_id`),
  KEY `fk_vt_firm_id` (`firm_id`),
  CONSTRAINT `fk_vt_bank_id` FOREIGN KEY (`bank_id`) REFERENCES `banks` (`id`),
  CONSTRAINT `fk_vt_firm_id` FOREIGN KEY (`firm_id`) REFERENCES `firms` (`id`),
  CONSTRAINT `fk_vt_vendor_id` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

