-- Dumping structure for procedure spire.XRay_Diagnostic
DROP PROCEDURE IF EXISTS `XRay_Diagnostic`;
DELIMITER //
CREATE PROCEDURE `XRay_Diagnostic`()
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE v_id INT;
    DECLARE v_old_custom_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE v_prefix VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE v_seq_key VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE v_final_prefix VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE v_new_custom_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE current_seq INT;
    
    -- Check what the cursor actually finds
    DECLARE cur CURSOR FOR 
        SELECT id, TRIM(custom_id), 
               TRIM(SUBSTRING_INDEX(TRIM(custom_id), '/', 1)) AS prefix
        FROM invoices
        WHERE custom_id NOT LIKE '%2024-25%'
        ORDER BY id ASC;
        
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    DROP TEMPORARY TABLE IF EXISTS seq_tracker_shared;
    CREATE TEMPORARY TABLE seq_tracker_shared (
        prefix VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci PRIMARY KEY,
        seq_val INT
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

    DROP TEMPORARY TABLE IF EXISTS invoice_updates_shared;
    CREATE TEMPORARY TABLE invoice_updates_shared (
        id INT PRIMARY KEY,
        old_custom_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
        new_custom_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO v_id, v_old_custom_id, v_prefix;
        IF done THEN LEAVE read_loop; END IF;
        
        IF UPPER(v_prefix) IN ('SCL', 'PSCL', 'SDS', 'PS') THEN
            SET v_seq_key = 'SCL_PSCL_SHARED';
        ELSE
            SET v_seq_key = UPPER(v_prefix);
        END IF;

        IF NOT EXISTS (SELECT 1 FROM seq_tracker_shared WHERE prefix = v_seq_key) THEN
        END IF;

        SELECT seq_val INTO current_seq FROM seq_tracker_shared WHERE prefix = v_seq_key;
        
        -- Blacklist Check 
        IF v_old_custom_id IN (
            'PSCL/2025-26/00078', 'PSCL/2025-26/00079',
            'PS/2025-26/00078', 'PS/2025-26/00079',
            'SCL/2025-26/00109', 'SCL/2025-26/00112', 'SCL/2025-26/00110', 'SCL/2025-26/00108',
            'SDS/2025-26/00109', 'SDS/2025-26/00112', 'SDS/2025-26/00110', 'SDS/2025-26/00108'
        ) THEN
            ITERATE read_loop;
        END IF;

        SET current_seq = current_seq + 1;
        
        WHILE (v_seq_key = 'SCL_PSCL_SHARED' AND current_seq IN (78, 79, 108, 109, 110, 112)) DO
            SET current_seq = current_seq + 1;
        END WHILE;

        UPDATE seq_tracker_shared SET seq_val = current_seq WHERE prefix = v_seq_key;
        
        IF v_seq_key = 'SCL_PSCL_SHARED' THEN
            IF current_seq <= 77 THEN
                SET v_final_prefix = 'PS';
            ELSE
                SET v_final_prefix = 'SDS';
            END IF;
        ELSE
            SET v_final_prefix = v_prefix;
        END IF;

        SET v_new_custom_id = CONCAT(v_final_prefix, '/2025-26/', LPAD(current_seq, 5, '0'));
        
        VALUES (v_id, v_old_custom_id, v_new_custom_id);
    END LOOP;
    CLOSE cur;
    
    -- X-RAY VISION: Show the mapped data instead of updating!
    SELECT id, old_custom_id, new_custom_id 
    FROM invoice_updates_shared;

END//
DELIMITER ;

